-- Errata reading for L36: Roster age_reported as captured at profile capture (not updated by later reported-age confirmations).
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','pharmacy_dispenses','demographic_updates')), c AS (SELECT patient, json_extract(payload,'$.description') d, coalesce(json_extract(payload,'$.icd10'),'') i, coalesce(json_extract(payload,'$.snomed'),'') s FROM r WHERE stream='conditions'), du AS (SELECT patient, json_extract(payload,'$.age_reported') a, json_extract(payload,'$.age_reference_date') ad FROM r WHERE stream='demographic_updates'), demo AS (SELECT p.id patient, json_extract(p.payload,'$.sex_reported') sex, json_extract(p.payload,'$.age_reported') age FROM patients p), dm AS (SELECT DISTINCT c.patient FROM c JOIN demo d ON d.patient=c.patient WHERE (substr(i,1,3) IN ('E10','E11','E13') OR s='44054006' OR (lower(d) LIKE '%diabetes mellitus%' AND lower(d) NOT LIKE 'family history%') OR d LIKE '%T1DM%' OR d LIKE '%T2DM%') AND d.age BETWEEN 40 AND 75), st AS (SELECT DISTINCT patient FROM (SELECT patient, json_extract(payload,'$.medication_name') m, payload FROM r WHERE stream='pharmacy_dispenses') WHERE json_extract(payload,'$.status')='dispensed' AND json_extract(payload,'$.event_date') BETWEEN '2028-01-01' AND '2028-12-31' AND (lower(m) LIKE '%atorvastatin%' OR lower(m) LIKE '%simvastatin%' OR lower(m) LIKE '%rosuvastatin%' OR lower(m) LIKE '%pravastatin%' OR lower(m) LIKE '%lovastatin%' OR lower(m) LIKE '%pitavastatin%' OR lower(m) LIKE '%fluvastatin%')) SELECT round(100.0*SUM(patient IN (SELECT patient FROM st))/COUNT(*),1) AS value FROM dm;
